import verified from './ranges-dcfr-9max.json?v=b69dba35' with {type:'json'};
/* Introductory hand-range examples, not solver output. */
const ranks='AKQJT98765432'.split('');
const scenarios={
 'open':{title:'ABERTURA · PRIMEIRO A ENTRAR',hint:'Exemplo simplificado: mãos que podem ser consideradas para abrir quando ninguém aumentou antes.',groups:{early:['AA','KK','QQ','JJ','TT','AKs','AQs','AKo'],middle:['AA','KK','QQ','JJ','TT','99','88','AKs','AQs','AJs','KQs','AKo','AQo'],late:['AA','KK','QQ','JJ','TT','99','88','77','66','AKs','AQs','AJs','ATs','KQs','KJs','QJs','JTs','AKo','AQo','AJo','KQo']},action:'ABRIR / RAISE'},
 'call':{title:'CALL · PAGAR UM RAISE',hint:'Exemplo de mãos candidatas a avaliar contra uma abertura. O call depende do tamanho da aposta, posição e adversário.',groups:{early:['QQ','JJ','TT','99','AKs','AQs'],middle:['JJ','TT','99','88','AQs','AJs','KQs'],late:['TT','99','88','77','66','AJs','ATs','KQs','QJs','JTs']},action:'CONSIDERAR CALL'},
 'threebet':{title:'RE-RAISE · 3-BET',hint:'Exemplos de mãos fortes para compreender o aumento sobre uma abertura. Não é uma frequência ótima de 3-bet.',groups:{early:['AA','KK','QQ','AKs','AKo'],middle:['AA','KK','QQ','JJ','AKs','AQs','AKo'],late:['AA','KK','QQ','JJ','TT','AKs','AQs','AJs','AKo','AQo']},action:'CONSIDERAR 3-BET'},
 'shove':{title:'ALL-IN · STACK CURTO',hint:'Apenas exemplos de mãos fortes para estudar um all-in pré-flop. A decisão real depende especialmente do stack efetivo.',groups:{early:['AA','KK','QQ','AKs'],middle:['AA','KK','QQ','JJ','AKs','AKo'],late:['AA','KK','QQ','JJ','TT','AKs','AQs','AKo']},action:'ESTUDAR ALL-IN'},
 'callshove':{title:'CALL ALL-IN · PAGAR UM SHOVE',hint:'Exemplos conservadores de mãos fortes. Não use esta seleção como recomendação automática para pagar all-in.',groups:{early:['AA','KK'],middle:['AA','KK','QQ'],late:['AA','KK','QQ','AKs']},action:'AVALIAR CALL ALL-IN'}
};
const groupFor=pos=>['UTG','UTG+1','MP','LJ'].includes(pos)?'early':['HJ','CO'].includes(pos)?'middle':'late';
const hand=(i,j)=>i===j?ranks[i]+ranks[j]:i<j?ranks[i]+ranks[j]+'s':ranks[j]+ranks[i]+'o';
export function rangesLibrary(){return `<section class="ranges-library"><details class="ranges-entry"><summary><strong>CONSULTAR RANGES BÁSICOS</strong><span>Filtre situações comuns e visualize as mãos na tabela</span></summary><div class="ranges-library-inner"><p>Como o Academy é um aplicativo para iniciantes, nesta introdução aos ranges consideramos apenas mesas completas de <strong>9 jogadores (9-max)</strong>. Os ranges mudam conforme a <strong>quantidade de jogadores na mesa</strong>, pois as posições, a frequência dos blinds e as oportunidades de ação são diferentes. Por isso, os exemplos apresentados aqui não devem ser aplicados automaticamente a mesas com menos jogadores. As tabelas mostram exemplos introdutórios e frequências disponíveis para determinadas aberturas; as demais situações são <strong>exemplos didáticos</strong>. As decisões também variam conforme stack, apostas e adversários. Situações sem referência de solver independente são exemplos didáticos: <strong>NÃO VALIDADO</strong>.</p><div class="ranges-filters"><label>MESA<select id="ranges-table"><option value="9">9 JOGADORES</option></select></label><label>STACK EFETIVO<select id="ranges-stack"><option value="10">10 BB</option><option value="15">15 BB</option><option value="30">30 BB</option><option value="100" selected>100 BB</option></select></label><label>STREET<select id="ranges-street"><option value="pre">PRÉ-FLOP</option><option value="flop">FLOP</option><option value="turn">TURN</option><option value="river">RIVER</option></select></label><label>POSIÇÃO<select id="ranges-position">${['UTG','UTG+1','UTG+2','LJ','HJ','CO','BTN','SB','BB'].map(p=>`<option value="${p}" ${p==='BTN'?'selected':''}>${p}</option>`).join('')}</select></label><label>SITUAÇÃO<select id="ranges-scenario">${Object.entries(scenarios).map(([k,v])=>`<option value="${k}">${v.title}</option>`).join('')}</select></label></div><div class="ranges-output" aria-live="polite"></div></div></details></section>`}
export function setupRangesLibrary(root){const el=root.querySelector('.ranges-library');if(!el)return;const table=el.querySelector('#ranges-table'),stack=el.querySelector('#ranges-stack'),street=el.querySelector('#ranges-street'),pos=el.querySelector('#ranges-position'),scenario=el.querySelector('#ranges-scenario'),out=el.querySelector('.ranges-output');// Replace native Android select popups with accessible inline filter drawers.
 [table,stack,street,pos,scenario].forEach(select=>{
  const label=select.closest('label');if(!label)return;
  select.hidden=true;select.setAttribute('aria-hidden','true');select.tabIndex=-1;
  const trigger=document.createElement('button');trigger.type='button';trigger.className='ranges-filter-trigger';trigger.setAttribute('aria-expanded','false');
  const drawer=document.createElement('div');drawer.className='ranges-filter-drawer';drawer.hidden=true;
  function sync(){trigger.textContent=select.selectedOptions[0]?.textContent||'SELECIONAR';drawer.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===select.value)))}
  Array.from(select.options).forEach(option=>{const button=document.createElement('button');button.type='button';button.dataset.value=option.value;button.textContent=option.textContent;button.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));drawer.hidden=true;trigger.setAttribute('aria-expanded','false');sync();trigger.focus()});drawer.append(button)});
  trigger.addEventListener('click',()=>{const opening=drawer.hidden;el.querySelectorAll('.ranges-filter-drawer').forEach(d=>d.hidden=true);el.querySelectorAll('.ranges-filter-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));drawer.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening))});
  label.append(trigger,drawer);sync();
 });
 const update=()=>{const st=street.value,sc=scenarios[scenario.value],position=pos.value;if(st!=='pre'){out.innerHTML=`<h3>${{flop:'FLOP',turn:'TURN',river:'RIVER'}[st]} · ${position}</h3><p>Nas streets pós-flop, os ranges dependem das cartas comunitárias, das apostas anteriores e dos stacks. Observe mãos feitas, projetos e blefes possíveis. Não há tabela fixa confiável sem definir o board e a sequência de ações.</p>`;return}const solved=table.value==='9'&&scenario.value==='open'&&verified.scenarios[stack.value+'|'+position];const frequencies=solved?Object.fromEntries(solved.actions.map(([h,...actions])=>[h,actions.filter(a=>a[0]==='raise').reduce((n,a)=>n+a[1],0)])):null;const chosen=new Set(sc.groups[groupFor(position)]);out.innerHTML=`<h3>${sc.title}</h3><p><strong>${position}</strong> · ${sc.hint}</p>${solved?`<p><strong>RANGE DE ABERTURA · 9 JOGADORES</strong> · ${stack.value} BB. Células amarelas: frequência de raise de pelo menos 50%; consulte cada mão para ver a frequência.</p>`:`<p><strong>EXEMPLO DIDÁTICO.</strong> Esta seleção é apenas uma introdução e não representa uma recomendação para todas as situações.</p>`}<div class="ranges-matrix" role="table" aria-label="Tabela educativa de 169 classes de mãos">${ranks.map((_,i)=>ranks.map((_,j)=>{const h=hand(i,j);return `<span role="cell" class="${(frequencies?frequencies[h]>=50:chosen.has(h))?'range-selected':'range-muted'}" title="${h}${frequencies?` · RAISE ${frequencies[h]?.toFixed(1)}%`: ''}">${h}</span>`}).join('')).join('')}</div><div class="ranges-key"><span class="range-key-on"></span> ${sc.action} <span class="range-key-off"></span> FORA DESTE EXEMPLO</div><p>Suited (s): mesmo naipe. Offsuit (o): naipes diferentes. Pares: duas cartas do mesmo valor. Esta tabela não define mãos obrigatórias nem garante lucro.</p>`};[table,stack,street,pos,scenario].forEach(c=>c.addEventListener('change',update));update()}
